import socketserver,struct
def exact(sock,n):
    data=b''
    while len(data)<n:
        more=sock.recv(n-len(data))
        if not more:raise EOFError('truncated frame')
        data+=more
    return data
@contextlib.contextmanager
def framed(label):
    records=[]
    class Handler(socketserver.BaseRequestHandler):
        def handle(self):
            self.request.settimeout(2)
            try:
                while True:
                    size=struct.unpack('!H',exact(self.request,2))[0];payload=exact(self.request,size);records.append(payload)
                    body=label+payload;self.request.sendall(struct.pack('!H',len(body))+body)
            except (EOFError,OSError):pass
    class Server(socketserver.ThreadingTCPServer):allow_reuse_address=True;daemon_threads=False
    s=Server(('127.0.0.1',0),Handler);t=threading.Thread(target=s.serve_forever,kwargs={'poll_interval':.01});t.start()
    try:yield s.server_address[1],records
    finally:s.shutdown();s.server_close();t.join(1);assert not t.is_alive()

with framed(b'A:') as (a,ar),framed(b'B:') as (b,br):
    with nginx({'A':a,'B':b}) as p:
        labels=[]
        for i in range(6):
            with socket.create_connection(('127.0.0.1',p),timeout=2) as c:
                seen=[]
                for payload in [b'\x00\n'+secrets.token_bytes(17),b'']:
                    wire=struct.pack('!H',len(payload))+payload;c.sendall(wire[:1]);c.sendall(wire[1:])
                    reply=exact(c,struct.unpack('!H',exact(c,2))[0]);assert reply[2:]==payload and reply[:2] in [b'A:',b'B:'];seen.append(reply[:2])
                assert seen[0]==seen[1];labels.append(seen[0])
        assert labels.count(b'A:')==labels.count(b'B:')==3 and len(ar)==len(br)==6,(labels,ar,br)

