import re,threading,time
class Quota:
    def __init__(self,limit,window,clock=time.monotonic,max_keys=128):
        self.limit=limit;self.window=window;self.clock=clock;self.max_keys=max_keys
        self.lock=threading.Lock();self.entries={}
    def allow(self,key):
        if not isinstance(key,str) or not re.fullmatch(r'[A-Za-z0-9_-]{1,64}',key):return False
        with self.lock:
            now=self.clock()
            self.entries={k:v for k,v in self.entries.items() if now-v[0]<self.window}
            if key not in self.entries:
                if len(self.entries)>=self.max_keys:return False
                self.entries[key]=[now,0]
            item=self.entries[key]
            if item[1]>=self.limit:return False
            item[1]+=1;return True
```

